void syscall_exit_trace(void *data, struct pt_regs *regs, long ret)
{
    int n = regs->ax;
    struct trace_array *tr = data;
    struct trace_array_cpu *td_cpu;
    struct ring_buffer_event *event;
    struct ring_buffer *buffer;
    struct ftrace_event_call *call;

    if (n < 0 || n >= __NR_syscalls)
        return;

    call = &sys_trace_event[n];
    if (!call->enabled)
        return;

    td_cpu = tr->data[raw_smp_processor_id()];
    buffer = td_cpu->buffer;
    event = ring_buffer_lock_reserve(buffer, call->event.size);
    if (!event)
        return;

    call->func(event, tr, td_cpu->cpu, regs, ret);
    ring_buffer_unlock_commit(buffer, event);
}

void handle_syscall_exit(void *data, struct pt_regs *regs, long ret)
{
    int syscall_nr = syscall_get_nr(current, regs);
    struct trace_array *tr = data;
    struct trace_event_file *file;

    if (syscall_nr < 0)
        return;

    file = find_event_file(tr, &sys_trace_event);
    if (!file || !file->enabled)
        return;

    if (!trace_event_try_reserve_entry(file))
        return;

    file->trace_fields[0].output(&file->trace_buffer, &file->fields[0], syscall_nr);
    file->trace_fields[1].output(&file->trace_buffer, &file->fields[1], ret);

    trace_event_commit(file);
}

